CONTEXTS = {
    '288': 'Jungle/cave expedition: fearful Lil is urged along by companions and Camille. Darkness gives Mikhail an opportunity; his mistaken contact is conveyed by another speaker\'s unfinished objection, without an invented body part or relationship. A tiger appears; attack risks shooting companions in cramped space, requires swords and causes injuries, while escape leads companions to infer it was not hungry. Light marks the exit. Keep personality variants, uncertainty and conditional outcomes distinct.',
    '289': 'Hostess and companions rebuke Lil\'s blunt response to an elder of a nearby village. He believes she can find an ancient kingdom\'s temple, begins a warning, then dismisses it with laughter. Elder is an actual village role, not invented kinship; no new prophecy or condition.',
    '290': 'One Angkor hint path recalls the new-star riddle, sun/gold, moon/silver and unknown starlight. Alchemy Book and New World author are reported leads; platinum is a proposed solution and southern Africa a tentative recollection. Lil jumps eagerly to conclusions without fully understanding. Do not invent a supernatural title or a book-acquisition outcome.',
    '291': 'Alternate Angkor hint path asks what star means, suggests a rare metal, then identifies platinum. Merchant vaguely recalls an alchemy book by someone who went to the New World a dozen or more years ago; the book is needed for the commodity. Another state recognizes the book and urges loading platinum. Africa location and purchase advice remain.',
    '292': 'Entity asks to be adorned with a new star\'s pure radiance. Party hauls platinum; entity praises wisdom, commands a storm at sea and peaceful sleep. Lil notices an old coin; companions speculate about its use. No precise item name, deity rank, confirmed power or actual storm outcome is invented.',
}


def main():
    out = ROOT / 'authored_B288_B292_v1.json'
    assert not out.exists()
    records = []
    active = None
    for line in TEXT.splitlines():
        if not line:
            continue
        if line.startswith('@'):
            active = line[1:]
            continue
        assert active in CONTEXTS
        records.append(line.split('|', 2))
    assert len(records) == 134
    save(out, dict(contexts=CONTEXTS, records=records, whole_clean_exchanges_read_before_drafting=True,
        current_English_not_consulted=True, source_name_item_title_andnative_consumer_bindings_pending=True, new_credit=0))


if __name__ == '__main__':
    main()
